// Builds this week's digest as a HubSpot task from the company search result.
// Company names come from outside data, so every value is HTML-escaped.
const result = $input.first().json;
const companies = result.results || [];
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const today = new Date().toISOString().slice(0, 10);
const total = result.total ?? companies.length;
const flagged = companies.filter((company) => (company.properties || {}).signal_flags).length;
const lines = companies.map((company) => {
  const p = company.properties || {};
  const flags = p.signal_flags ? ' Flags: ' + esc(p.signal_flags.split('\n').join('; ')) + '.' : '';
  return '<li><strong>' + esc(p.name) + '</strong> (' + esc(p.domain) + '): score ' + esc(p.signal_score)
    + ', ' + esc(p.signal_tier) + '.' + flags + '</li>';
});
const more = total > companies.length ? ' Showing the first ' + companies.length + '.' : '';
const body = companies.length
  ? '<p>' + total + ' new account(s) in the last 7 days, ' + flagged + ' with a flag from the rules.' + more
    + '</p><ul>' + lines.join('') + '</ul>'
  : '<p>No new accounts in the last 7 days.</p>';
const task = {
  properties: {
    hs_timestamp: new Date().toISOString(),
    hs_task_subject: 'Signal digest ' + today + ': ' + total + ' new account(s)',
    hs_task_body: body,
    hs_task_status: 'NOT_STARTED',
    hs_task_priority: 'LOW',
    hs_task_type: 'TODO',
  },
};
if ($env.DIGEST_NO_TASK === '1') {
  return [];  // read-only run: nothing goes on to the node that creates the task
}
return [{ json: { task, new_accounts: total, flagged } }];
